	for (const u of STAFF_SEED) {
		const found = await sql`select id from "user" where email = ${u.email}`;
		const id = found[0]?.id ?? crypto.randomUUID();
		if (!found.length) await sql`insert into "user" (id, name, email, "emailVerified") values (${id}, ${u.name}, ${u.email}, true)`;
		const acc = await sql`
      select id from "account" where "userId" = ${id} and "providerId" = ${"credential"}`;
		if (acc.length) await sql`update "account" set password = ${DEMO_PASSWORD_HASH}, "updatedAt" = now() where id = ${acc[0].id}`;
		else await sql`insert into "account" (id, "accountId", "providerId", "userId", password, "createdAt", "updatedAt")
        values (${crypto.randomUUID()}, ${id}, ${"credential"}, ${id}, ${DEMO_PASSWORD_HASH}, now(), now())`;
	}
